/**
 * Offline Cryptographic License Engine
 * 
 * In a real production environment, this would use tweetnacl (Ed25519) 
 * or the Web Crypto API to verify an RSA-SHA256 signature generated by your 
 * payment provider (LemonSqueezy/Stripe).
 * 
 * For this implementation, we will simulate the cryptographic verification 
 * that checks if a license string is structurally valid and mathematically signed.
 */

const LICENSE_STORAGE_KEY = "mld_pro_license";

export type LicenseTier = "free_core" | "pro_monthly" | "pro_yearly" | "pro_6month" | "pro_lifetime";

export interface LicenseStatus {
  tier: LicenseTier;
  email?: string;
  isValid: boolean;
  message: string;
  expiresAt?: string;
}

/**
 * Checks the current license status from local storage.
 * Defaults to free_core if no valid license exists.
 */
export function getLicenseStatus(): LicenseStatus {
  const storedLicense = localStorage.getItem(LICENSE_STORAGE_KEY);
  if (!storedLicense) {
    return { tier: "free_core", isValid: true, message: "Free Core Vault Active" };
  }

  return verifyLicenseKey(storedLicense);
}

/**
 * Verifies a cryptographic license key string.
 * Format: `MLD-PRO-base64EncodedPayload.signature`
 */
export function verifyLicenseKey(licenseString: string): LicenseStatus {
  try {
    const trimmed = licenseString.trim();
    if (!trimmed.startsWith("MLD-PRO-")) {
      throw new Error("Invalid license format.");
    }

    const parts = trimmed.substring(8).split(".");
    if (parts.length !== 2) {
      throw new Error("Invalid signature parts.");
    }

    const [payloadB64, signature] = parts;
    const payloadJson = atob(payloadB64);
    const payload = JSON.parse(payloadJson);

    // MOCK SIGNATURE VERIFICATION: 
    // In production, hash payloadJson and compare against decrypted RSA signature.
    if (signature.length < 16) {
      throw new Error("Cryptographic signature invalid.");
    }

    // CHECK SUBSCRIPTION EXPIRATION
    if (payload.expiresAt) {
      const expirationDate = new Date(payload.expiresAt);
      if (new Date() > expirationDate) {
        throw new Error("Your subscription has expired.");
      }
    }

    return {
      tier: payload.tier || "pro_yearly",
      email: payload.email,
      isValid: true,
      expiresAt: payload.expiresAt,
      message: payload.expiresAt 
        ? `Pro Subscription Active (Valid until ${new Date(payload.expiresAt).toLocaleDateString()})` 
        : "Pro Lifetime License Active"
    };

  } catch (error) {
    return {
      tier: "free_core",
      isValid: false,
      message: error instanceof Error ? error.message : "License validation failed."
    };
  }
}

/**
 * Saves a successfully verified license key to local storage.
 */
export function activateLicense(licenseString: string): boolean {
  const status = verifyLicenseKey(licenseString);
  if (status.isValid && status.tier !== "free_core") {
    localStorage.setItem(LICENSE_STORAGE_KEY, licenseString.trim());
    return true;
  }
  return false;
}

/**
 * Removes the license and downgrades back to free core.
 */
export function removeLicense(): void {
  localStorage.removeItem(LICENSE_STORAGE_KEY);
}

/**
 * DEVELOPMENT HELPER: Generates a mock valid license key for testing.
 * Do not use in production.
 */
export function __generateDevLicense(email: string, tier: LicenseTier = "pro_yearly"): string {
  if (!import.meta.env.DEV) {
    throw new Error("Development-only function.");
  }
  const expires = new Date();
  expires.setFullYear(expires.getFullYear() + 1);
  const payload = {
    email,
    tier,
    issuedAt: new Date().toISOString(),
    expiresAt: tier === "pro_lifetime" ? undefined : expires.toISOString()
  };
  const b64 = btoa(JSON.stringify(payload));
  const sig = "mock_signature_valid_for_dev_only_123456789";
  return `MLD-PRO-${b64}.${sig}`;
}
